import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster, mq } from "./tokens.stylex";
import { rs } from "./rs";

export interface CiteProps extends React.HTMLAttributes<HTMLElement> {}
export interface RefsProps extends React.OlHTMLAttributes<HTMLOListElement> {}
export interface RefItemProps extends React.LiHTMLAttributes<HTMLLIElement> {}
export interface CiteBoxProps extends React.HTMLAttributes<HTMLDivElement> {}


const styles = stylex.create({
  cite: {
    fontSize: 10.5,
    fontWeight: 600,
    letterSpacing: 0,
    lineHeight: 0,
    verticalAlign: "super",
    whiteSpace: "nowrap",
  },
  citeA: {
    color: {
      default: raster.gray,
      ":hover": raster.accent,
    },
    textDecoration: "none",
    transition: "color var(--duration-snap) var(--ease)",
  },
  refs: {
    listStyle: "none",
    counterReset: "ref",
    marginTop: 4,
    marginBottom: 8,
    marginInlineStart: 0,
    marginInlineEnd: 0,
    padding: 0,
  },
  item: {
    counterIncrement: "ref",
    position: "relative",
    paddingTop: 10,
    paddingBottom: 10,
    fontSize: 13,
    fontWeight: 500,
    lineHeight: 1.65,
    color: raster.gray,
    letterSpacing: "-0.01em",
    borderBottomWidth: raster.hairline,
    borderBottomStyle: "solid",
    borderBottomColor: {
      default: raster.divider,
      ":last-child": "transparent",
    },
    scrollMarginTop: 88,
    ":target": {
      backgroundColor: "var(--table-alt)",
    },
    "::before": {
      content: "counter(ref)",
      position: "absolute",
      insetInlineStart: -16,
      top: 11,
      width: 12,
      textAlign: "end",
      fontSize: 11,
      fontWeight: 600,
      color: "var(--accent)",
    },
  },
  authors: {
    color: "var(--text)",
    fontWeight: 500,
  },
  doi: {
    fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace",
    fontSize: 11,
    color: {
      default: raster.gray,
      ":hover": "var(--text)",
    },
    textDecoration: "none",
    borderBottomWidth: raster.hairline,
    borderBottomStyle: "solid",
    borderBottomColor: {
      default: raster.divider,
      ":hover": raster.accent,
    },
    transition: "color var(--duration-snap) var(--ease), border-color var(--duration-snap) var(--ease)",
    wordBreak: "break-all",
  },
  box: {
    borderWidth: raster.hairline,
    borderStyle: "solid",
    borderColor: raster.divider,
    borderRadius: raster.radius,
    padding: {
      default: 20,
      [mq.phone]: "14px 16px",
    },
    marginTop: 8,
  },
  boxLabel: {
    fontSize: 12,
    fontWeight: 600,
    color: raster.gray,
    letterSpacing: "-0.01em",
    marginBottom: 8,
  },
  boxText: {
    fontSize: 13,
    fontWeight: 500,
    color: raster.gray,
    lineHeight: 1.7,
    userSelect: "all",
  },
});

/** Inline superscript citation. */
export const Cite = React.forwardRef<HTMLElement, CiteProps>(function Cite(
  { className, style, children, ...props },
  ref,
) {
  const sx = rs(["rs-cite", className], styles.cite);
  return (
    <sup ref={ref} {...props} className={sx.className} style={{ ...sx.style, ...style }}>
      {children}
    </sup>
  );
});

export const CiteLink = React.forwardRef<HTMLAnchorElement, React.AnchorHTMLAttributes<HTMLAnchorElement>>(function CiteLink(
  { className, style, ...props },
  ref,
) {
  const sx = rs([className, "rs-cite-cite-a"], styles.citeA);
  return <a ref={ref} {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
});

/** Numbered 1px list. Numerals hang in the gutter. */
export const Refs = React.forwardRef<HTMLOListElement, RefsProps>(function Refs(
  { className, style, ...props },
  ref,
) {
  const sx = rs(["rs-refs", className], styles.refs);
  return <ol ref={ref} {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
});

export const RefItem = React.forwardRef<HTMLLIElement, RefItemProps>(function RefItem(
  { className, style, ...props },
  ref,
) {
  const sx = rs([className, "rs-cite-item"], styles.item);
  return <li ref={ref} {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
});

export const RefAuthors = React.forwardRef<HTMLSpanElement, React.HTMLAttributes<HTMLSpanElement>>(function RefAuthors(
  { className, style, ...props },
  ref,
) {
  const sx = rs(["rs-ref-authors", className], styles.authors);
  return <span ref={ref} {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
});

export const RefDoi = React.forwardRef<HTMLAnchorElement, React.AnchorHTMLAttributes<HTMLAnchorElement>>(function RefDoi(
  { className, style, ...props },
  ref,
) {
  const sx = rs(["rs-ref-doi", className], styles.doi);
  return <a ref={ref} {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
});

export const CiteBox = React.forwardRef<HTMLDivElement, CiteBoxProps>(function CiteBox(
  { className, style, ...props },
  ref,
) {
  const sx = rs(["rs-cite-box", className], styles.box);
  return <div ref={ref} {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
});

export const CiteBoxLabel = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(function CiteBoxLabel(
  { className, style, ...props },
  ref,
) {
  const sx = rs(["rs-cite-box-label", className], styles.boxLabel);
  return <div ref={ref} {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
});

export const CiteBoxText = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(function CiteBoxText(
  { className, style, ...props },
  ref,
) {
  const sx = rs(["rs-cite-box-text", className], styles.boxText);
  return <div ref={ref} {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
});

/* ── references: generated from packages/react/src/components/refs.tsx ── */
.rs-cite{font-size:10.5px;font-weight:600;letter-spacing:0;line-height:0;vertical-align:super;white-space:nowrap}
.rs-cite-cite-a{color:var(--text-secondary);text-decoration:none;transition:color var(--duration-snap) var(--ease)}
.rs-cite-cite-a:hover{color:var(--accent)}
.rs-refs{list-style:none;counter-reset:ref;margin-top:4px;margin-bottom:8px;margin-inline-start:0;margin-inline-end:0;padding:0}
.rs-cite-item{counter-increment:ref;position:relative;padding-top:10px;padding-bottom:10px;font-size:13px;font-weight:500;line-height:1.65;color:var(--text-secondary);letter-spacing:-0.01em;border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--divider);scroll-margin-top:88px}
.rs-cite-item:last-child{border-bottom-color:transparent}
.rs-cite-item:target{background-color:var(--table-alt)}
.rs-cite-item::before{content:counter(ref);position:absolute;inset-inline-start:-16px;top:11px;width:12px;text-align:end;font-size:11px;font-weight:600;color:var(--accent)}
.rs-ref-authors{color:var(--text);font-weight:500}
.rs-ref-doi{font-family:ui-monospace, SFMono-Regular, Menlo, monospace;font-size:11px;color:var(--text-secondary);text-decoration:none;border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--divider);transition:color var(--duration-snap) var(--ease), border-color var(--duration-snap) var(--ease);word-break:break-all}
.rs-ref-doi:hover{color:var(--text);border-bottom-color:var(--accent)}
.rs-cite-box{border-width:1px;border-style:solid;border-color:var(--divider);border-radius:var(--radius);padding:20px;margin-top:8px}
@media (max-width: 640px){.rs-cite-box{padding:14px 16px}}
.rs-cite-box-label{font-size:12px;font-weight:600;color:var(--text-secondary);letter-spacing:-0.01em;margin-bottom:8px}
.rs-cite-box-text{font-size:13px;font-weight:500;color:var(--text-secondary);line-height:1.7;user-select:all}
